"""GF-2.0 FPC tails for the independent fit check - built HERE, not taken from the CAD agent's bodies.

Two sources, both from the master params (tail_route.*):
  * nominal  : the concept centre-line polylines tail_route.<TFT|CTP>.centreline_yZ (abs y, Z), swept along x over the
               developed outline tail_route.<..>.outline_developed = [v0, v1, x0, x1] (v = developed length from the
               panel edge), thickness tail_t;
  * variants : the same route re-generated by route() below (my own implementation of the route the concept describes:
               straight l0, bend R_c back (+Z), vertical straight, bend R_c over the nose to +y, front leg at Z_leg, U-loop,
               return leg at Z_return into the connector; the length L fixes the loop position). route() reproduces the
               params polylines (checked in compare_nominal) and is used for the tolerance cases (panel edge +-0.35, exit
               heights +-0.3, straight 1.0, R_in 1.8, tail 0.35).
Solids: per outline segment, the centre line is offset +-t/2 (mitred normals) into a closed (y, Z) polygon and extruded
along x between the segment's x0 and x1 (the cross-section is constant along x; the tails are flat FPC).
"""
import math
import sys

sys.dont_write_bytecode = True
import numpy as np
import cadquery as cq

import vcommon as C


# ------------------------------------------------------------------------------------------------ route
def tail_data(G, name):
    T = G.raw["tail_route"][name]
    return {k: T[k] for k in T}


def route(T, y_edge=None, Ze=None, l0=None, rc1=None, rc2=None, Z_leg=None, L=None, y_end=None, Z_ret=None, n_arc=40):
    """centre line (N x 2, abs y / Z) of the bent-back route. T = params tail_route entry (defaults)."""
    y_edge = 119.0 if y_edge is None else y_edge
    Ze = T["Z_exit"] if Ze is None else Ze
    l0 = T["straight"] if l0 is None else l0
    rc1 = T["R_centre"] if rc1 is None else rc1
    rc2 = T["R_centre"] if rc2 is None else rc2
    Z_leg = T["Z_leg"] if Z_leg is None else Z_leg
    L = T["L"] if L is None else L
    y_end = T["y_end"] if y_end is None else y_end
    Z_ret = T["Z_return"] if Z_ret is None else Z_ret
    dZ = Z_leg - Ze
    if dZ >= rc1 + rc2 - 1e-9:
        th, vert = math.pi / 2, dZ - rc1 - rc2
    else:
        th, vert = math.acos(1 - dZ / (rc1 + rc2)), 0.0
    pts = [(y_edge, Ze), (y_edge + l0, Ze)]
    c1 = (y_edge + l0, Ze + rc1)
    for k in range(1, n_arc + 1):
        a = th * k / n_arc
        pts.append((c1[0] + rc1 * math.sin(a), c1[1] - rc1 * math.cos(a)))
    if vert > 0:
        pts.append((pts[-1][0], pts[-1][1] + vert))
    p = pts[-1]
    c2 = (p[0] + rc2 * math.sin(th), p[1] - rc2 * math.cos(th))
    for k in range(1, n_arc + 1):
        a = th - th * k / n_arc
        pts.append((c2[0] - rc2 * math.sin(a), c2[1] + rc2 * math.cos(a)))
    y_s, Z_s = pts[-1]
    l_s = l0 + (rc1 + rc2) * th + vert
    r = (Z_ret - Z_s) / 2
    y_c = (L - l_s - math.pi * r + y_s + y_end) / 2
    pts.append((y_c, Z_s))
    for k in range(1, 2 * n_arc + 1):
        a = math.pi * k / (2 * n_arc)
        pts.append((y_c + r * math.sin(a), Z_s + r - r * math.cos(a)))
    pts.append((y_end, Z_ret))
    P = np.array(pts)
    return {"pts": P, "theta_deg": math.degrees(th), "vert": vert, "y_s": y_s, "Z_leg": Z_s, "U_R": r, "y_c": y_c,
            "loop_bottom_outer": y_c + r + 0.5 * T["thickness"], "length": float(np.sum(np.hypot(*np.diff(P, axis=0).T)))}


def polyline_dist(A, B, step=0.01):
    """max over A of the distance to polyline B (both N x 2), A densified"""
    from scipy.spatial import cKDTree
    Ad = densify(A, step)
    Bd = densify(B, step)
    d, _ = cKDTree(Bd).query(Ad)
    return float(d.max())


def densify(P, step):
    out = [P[0]]
    for a, b in zip(P[:-1], P[1:]):
        n = max(1, int(math.ceil(np.hypot(*(b - a)) / step)))
        for k in range(1, n + 1):
            out.append(a + (b - a) * k / n)
    return np.array(out)


def compare_nominal(G):
    """my route() vs the params polylines (max deviation both ways), and the params' scalar data vs the polyline"""
    res = {}
    for n in ("TFT", "CTP"):
        T = tail_data(G, n)
        P = np.array(T["centreline_yZ"])
        R = route(T)
        L_poly = float(np.sum(np.hypot(*np.diff(P, axis=0).T)))
        res[n] = {"max_dev_params_to_mine": round(polyline_dist(P, R["pts"]), 4),
                  "max_dev_mine_to_params": round(polyline_dist(R["pts"], P), 4),
                  "length_params_polyline": round(L_poly, 4), "length_mine": round(R["length"], 4), "L": T["L"],
                  "U_R_mine": round(R["U_R"], 4), "U_R_params": T["U_R"],
                  "loop_bottom_outer_mine": round(R["loop_bottom_outer"], 4), "loop_bottom_outer_params": T["loop_bottom_outer"],
                  "vertical_mine": round(R["vert"], 4), "vertical_params": T["vertical"],
                  "Z_leg_mine": round(R["Z_leg"], 4), "Z_leg_params": T["Z_leg"],
                  "front_leg_end_y_mine": round(R["y_c"], 4)}
    return res


# ------------------------------------------------------------------------------------------------ solids
def _cum(P):
    return np.concatenate([[0.0], np.cumsum(np.hypot(*np.diff(P, axis=0).T))])


def _cut(P, v0, v1):
    """sub-polyline between developed lengths v0 and v1 (interpolated end points)"""
    v = _cum(P)
    v1 = min(v1, v[-1])
    out = []
    def at(t):
        i = int(np.clip(np.searchsorted(v, t) - 1, 0, len(P) - 2))
        f = (t - v[i]) / max(v[i + 1] - v[i], 1e-12)
        return P[i] + f * (P[i + 1] - P[i])
    out.append(at(v0))
    for i in range(len(P)):
        if v0 + 1e-9 < v[i] < v1 - 1e-9:
            out.append(P[i])
    out.append(at(v1))
    return np.array(out)


def thick_polygon(P, h):
    """closed polygon (y, Z) of the polyline P offset +-h (mitred)"""
    d = np.diff(P, axis=0)
    d = d / np.linalg.norm(d, axis=1)[:, None]
    nseg = np.column_stack([-d[:, 1], d[:, 0]])
    nv = np.zeros_like(P)
    nv[0], nv[-1] = nseg[0], nseg[-1]
    for i in range(1, len(P) - 1):
        m = nseg[i - 1] + nseg[i]
        m /= np.linalg.norm(m)
        c = max(float(m @ nseg[i]), 0.5)
        nv[i] = m / c
    left, right = P + h * nv, P - h * nv
    return np.vstack([left, right[::-1]])


def _prism_x(poly_yZ, x0, x1):
    pts = [cq.Vector(x0, -y, z) for y, z in poly_yZ]
    w = cq.Wire.makePolygon(pts, close=True)
    f = cq.Face.makeFromWires(w)
    s = cq.Solid.extrudeLinear(f, cq.Vector(x1 - x0, 0, 0))
    if s.Volume() < 0:
        s = cq.Solid(s.wrapped.Reversed())
    return s


def tail_solids(G, name, P=None, t=None, v_from=0.0):
    """[(label, solid, (v0, v1, x0, x1))] of one tail along centre line P (default: params polyline)"""
    T = tail_data(G, name)
    P = np.array(T["centreline_yZ"]) if P is None else np.asarray(P)
    t = T["thickness"] if t is None else t
    out = []
    for v0, v1, x0, x1 in T["outline_developed"]:
        a, b = max(v0, v_from), v1
        if b <= a:
            continue
        sub = _cut(P, a, b)
        poly = thick_polygon(sub, t / 2)
        out.append(("%s v %.1f-%.1f" % (name, a, b), _prism_x(poly, x0, x1), (a, b, x0, x1)))
    return out


def bend_zone_criterion(G):
    """the bend-zone criterion block of the params (tail_clearance_criteria.bend_zone), with the GF-2.0 verification
    defaults when the block is absent"""
    c = (G.raw.get("tail_clearance_criteria") or {}).get("bend_zone") or {}
    contrib = c.get("panel_position_contributors_mm") or {"AA": 0.2, "J1": 0.1, "print": 0.2, "J2": 0.05, "core": 0.05}
    vals = [float(v) for v in contrib.values()]
    return {"min_at_RSS": float(c.get("clearance_min_at_RSS_mm", 0.45)), "min_at_WC": float(c.get("clearance_min_at_WC_mm", 0.0)),
            "rss": round(math.sqrt(sum(v * v for v in vals)), 3), "wc": round(sum(vals), 3),
            "exit_Z_tol": float(c.get("exit_Z_tol_mm", 0.3)), "tail_t_tol": float(c.get("tail_t_tol_mm", 0.05)),
            "features": list(BEND_KEYS),        # the params' feature list is descriptive; the classes are fixed here
            "alt_print_tol_wc": float(c.get("alternative_panel_position_WC_with_print_0.1_mm", round(sum(vals) - 0.1, 3)))}


def variant_routes(G):
    """tolerance cases: name -> {TFT: (centre line, thickness), CTP: (...)}"""
    cases = {}
    T = {n: tail_data(G, n) for n in ("TFT", "CTP")}
    cases["nominal (params polylines)"] = {n: np.array(T[n]["centreline_yZ"]) for n in T}
    for lab, kw in (("panel edge +0.35 (towards the bridge)", dict(y_edge=119.35)),
                    ("panel edge -0.35 (away from the bridge)", dict(y_edge=118.65)),
                    ("exit Z +0.3 (towards the PCB)", "ze+"), ("exit Z -0.3 (towards the glass)", "ze-"),
                    ("straight l0 1.0 instead of 0.5", dict(l0=1.0)),
                    ("inner bend radius 1.8 (centre 1.95)", dict(rc1=1.95, rc2=1.95)),
                    ("tail length +0.5", "L+"), ("tail length -0.5", "L-")):
        d = {}
        for n in T:
            if kw == "ze+":
                ze = T[n]["Z_exit"] + 0.3
                k = dict(Ze=ze, Z_leg=max(T[n]["Z_leg"], ze + 2 * T[n]["R_centre"]))
            elif kw == "ze-":
                k = dict(Ze=T[n]["Z_exit"] - 0.3)
            elif kw == "L+":
                k = dict(L=T[n]["L"] + 0.5)
            elif kw == "L-":
                k = dict(L=T[n]["L"] - 0.5)
            else:
                k = dict(kw)
                if "rc1" in k:
                    k["Z_leg"] = max(T[n]["Z_leg"], T[n]["Z_exit"] + 2 * k["rc1"])
            d[n] = route(T[n], **k)["pts"]
        cases[lab] = d
    for lab in list(cases):
        cases[lab] = {n: (P, T[n]["thickness"]) for n, P in cases[lab].items()}
    # bend-zone criterion cases (params tail_clearance_criteria.bend_zone): panel at its RSS position; worst case = panel at
    # its WC position, exit height at either limit, tail at its upper thickness (inner radius kept at tail_R_in_min); and the
    # alternative with print-to-edge +-0.1
    bc = bend_zone_criterion(G)
    r_in = float(G.tail_R_in_min or 1.5)
    def rt(n, dy, dz, t):
        ze = T[n]["Z_exit"] + dz
        rc = r_in + t / 2
        return route(T[n], y_edge=119.0 + dy, Ze=ze, rc1=rc, rc2=rc, Z_leg=max(T[n]["Z_leg"], ze + 2 * rc))["pts"]
    cases["bend-zone RSS: panel edge +%.3f" % bc["rss"]] = {n: (rt(n, bc["rss"], 0.0, T[n]["thickness"]), T[n]["thickness"]) for n in T}
    for sg in (-1, 1):
        cases["bend-zone WC: panel edge +%.2f, exit Z %+.1f, tail %.2f" % (bc["wc"], sg * bc["exit_Z_tol"], 0.3 + bc["tail_t_tol"])] = {
            n: (rt(n, bc["wc"], sg * bc["exit_Z_tol"], T[n]["thickness"] + bc["tail_t_tol"]), T[n]["thickness"] + bc["tail_t_tol"]) for n in T}
        cases["alternative print-to-edge +-0.1, WC: panel edge +%.2f, exit Z %+.1f, tail %.2f" % (bc["alt_print_tol_wc"], sg * bc["exit_Z_tol"],
                                                                                              0.3 + bc["tail_t_tol"])] = {
            n: (rt(n, bc["alt_print_tol_wc"], sg * bc["exit_Z_tol"], T[n]["thickness"] + bc["tail_t_tol"]), T[n]["thickness"] + bc["tail_t_tol"]) for n in T}
    cases["bend-zone WC, panel position only: panel edge +%.2f" % bc["wc"]] = {n: (rt(n, bc["wc"], 0.0, T[n]["thickness"]), T[n]["thickness"]) for n in T}
    return cases


# ------------------------------------------------------------------------------------------------ frame faces near the tails
# class labels (revision-neutral: the y values come from the params; used as keys by fit_check, calc_gf, sections_gf)
K_NOSE = "bridge nose R1.5"
K_BREAK = "land break 0.3 x 45"
K_FACE = "bridge pocket face (+ rib front)"
K_LPB = "land-plate back (bridge floor, Z -7.92)"
K_FLOOR = "flange plate = pocket floor (Z -9.92)"
K_STEP = "step face (step-wall back, + root round)"
K_BOTTOM = "pocket bottom face y 147.7 / bottom wall"
K_SIDE = "tail-pocket side walls x 38.9 / 167.7 (+ corners)"
K_SLOT = "slot ends / shelf end y 119.0 / shelf / ribs"
K_RIB = "divider rib (sides, top, roots)"
K_LAND = "land Z -10.42 (bead face)"
BEND_KEYS = (K_NOSE, K_FACE, K_BREAK)


def classify_frame_faces(fr, G):
    """frame faces in the tail zone grouped by the feature they belong to (names used in the clearance table)"""
    from OCP.BRepAdaptor import BRepAdaptor_Surface
    L = G.L
    bx0, bx1 = G.TAIL[0], G.TAIL[1]
    xr = float(G.drv.get("div_x", 79.92))
    rib_half = float(G.drv.get("div_t", 2.5)) / 2 + 0.6
    y_pf = float(G.rect["bend_gap_slot"]["y1"])          # bridge pocket face at Z_LAND
    y_st = float(G.rect["bridge"]["y1"])                 # step-wall back (bridge rect y1)
    y_bw = float(G.TAIL[3])                              # tail-pocket bottom face
    groups = {}
    for f in fr.Faces():
        bb = f.BoundingBox()
        ya0, ya1 = -bb.ymax, -bb.ymin
        if bb.xmax < bx0 - 3 or bb.xmin > bx1 + 3 or ya1 < 112 or ya0 > 151 or bb.zmax < -11.0:
            continue
        c = f.Center()
        cx, cy, cz = c.x, -c.y, c.z
        gt = f.geomType()
        ad = BRepAdaptor_Surface(f.wrapped)
        n = f.normalAt() if gt == "PLANE" else None
        k = "other"
        if gt == "CYLINDER" and abs(ad.Cylinder().Radius() - float(G.drv.get("bend_nose_R", 1.5))) < 0.01 and \
                abs(ad.Cylinder().Axis().Direction().X()) > 0.99:
            k = K_NOSE
        elif gt == "PLANE" and 0.6 < abs(n.z) < 0.8 and ya1 < y_pf + 0.5:
            k = K_BREAK
        elif abs(cx - xr) < rib_half and ya1 > y_pf + 0.05 and not (gt == "PLANE" and abs(n.y) > 0.99 and ya1 - ya0 < 0.3 and bb.xmax - bb.xmin > 10):
            k = K_RIB
        elif gt == "PLANE" and abs(n.y) > 0.99 and -n.y < 0 and abs(ya0 - y_pf) < 0.25:
            k = K_FACE
        elif gt == "PLANE" and n.z > 0.99 and abs(cz - L["Z_LANDPLATE_BACK"]) < 0.01:
            k = K_LPB
        elif gt == "PLANE" and n.z > 0.99 and abs(cz - L.get("Z_FLOOR_LOW", L["Z_FLANGE_BACK"])) < 0.01:
            k = K_FLOOR
        elif ya0 > y_st - 0.3 and ya1 < y_st + 0.6 and cz < L["Z_LANDPLATE_BACK"] + 0.1:
            k = K_STEP
        elif ya0 > y_bw - 1.7 and cz > L["Z_FLANGE_BACK"] - 0.1 and (abs(cx - bx0) > 2.2 and abs(cx - bx1) > 2.2):
            k = K_BOTTOM
        elif (abs(cx - bx0) < 2.2 or abs(cx - bx1) < 2.2) and ya1 > y_pf + 1.0:
            k = K_SIDE
        elif ya1 < y_pf - 0.1 or (abs(cx - bx0) < 2.2 or abs(cx - bx1) < 2.2):
            k = K_SLOT
        elif cz > L["Z_FLANGE_BACK"] - 0.1 and ya0 > y_st + 0.1 and ya1 < y_bw + 0.1:
            k = "floor root rounds"
        elif cz > 3.9:
            k = "trough top Z 4.05"
        groups.setdefault(k, []).append(f)
    return groups


def dist_min(shapes_a, shapes_b):
    """min distance and points between two lists of shapes (BRepExtrema on compounds)"""
    a = cq.Compound.makeCompound(shapes_a) if len(shapes_a) > 1 else shapes_a[0]
    b = cq.Compound.makeCompound(shapes_b) if len(shapes_b) > 1 else shapes_b[0]
    return C.dist_pts(a, b)
